  static DentalTool Tools(DentistMatch m,ServingArm arm,Material steel,Material teal,Material ivory,PhysicsMaterial contact){var tool=arm.grip.gameObject.AddComponent<DentalTool>();tool.match=m;tool.arm=arm;tool.models=new Transform[6];tool.tips=new SphereCollider[6];for(int i=0;i<6;i++){var g=new GameObject("Actual selected "+(DentalToolKind)i);g.layer=2;g.transform.SetParent(arm.grip.transform,false);g.transform.localPosition=Vector3.forward*1.2f;tool.models[i]=g.transform;Part(g.transform,"Molded ergonomic dental grip",teal,new Vector3(0,0,-.6f),new Vector3(.55f,.5f,1.4f));Part(g.transform,"Actual machined tool shaft",steel,new Vector3(0,0,.2f),new Vector3(.13f,.13f,1.2f));if(i==0){Part(g.transform,"Toothbrush head",ivory,new Vector3(0,0,.85f),new Vector3(.7f,.22f,.65f));for(int b=0;b<18;b++)Part(g.transform,"Individual brush bristle tuft",teal,new Vector3((b%3-1)*.18f,.22f,.6f+b/3*.09f),new Vector3(.09f,.3f,.055f));}else if(i==1){ServingArt.Part(Folder,g.transform,"Actual rotary drill head",ServingArt.Mesh(Folder,"Machined tapered dental drill",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(.18f,0),new Vector2(.1f,.25f),new Vector2(.055f,.8f),new Vector2(0,.9f)},20)),steel,new Vector3(0,0,.4f),Vector3.one).transform.localRotation=Quaternion.Euler(90,0,0);}else if(i==2){for(int side=-1;side<=1;side+=2){var jaw=Part(g.transform,"Curved extraction forceps jaw",steel,new Vector3(side*.2f,0,.6f),new Vector3(.13f,.28f,.7f));jaw.transform.localRotation=Quaternion.Euler(0,side*-18,0);}Part(g.transform,"Extraction forceps hinge",teal,new Vector3(0,0,.3f),new Vector3(.6f,.32f,.25f));}else if(i==3||i==4){var tip=ServingArt.Part(Folder,g.transform,"Bent hygienic air/water nozzle",ServingArt.Spout(Folder),steel,new Vector3(0,-.12f,.3f),Vector3.one*.25f);Round(g.transform,"Blue/red nozzle control",i==4?teal:ivory,new Vector3(0,.25f,-.5f),Vector3.one*.22f);}else{Round(g.transform,"Cleaning and filling polishing pad",ivory,new Vector3(0,0,.85f),new Vector3(.5f,.5f,.35f));Serv