  static DentalTooth Tooth(DentistMatch m,Transform parent,int id,Vector3 position,Material enamel,Material gums,Material plaque,Material dark,Material filling,PhysicsMaterial contact){var g=new GameObject("Actual physical "+DentalRules.Task(id)+" tooth "+id);g.transform.SetParent(parent,false);g.transform.position=position;g.layer=2;var body=g.AddComponent<Rigidbody>();body.mass=90;body.isKinematic=true;body.linearDamping=.3f;body.angularDamping=.3f;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.maxDepenetrationVelocity=1.5f;g.AddComponent<ServingSupport>();var tooth=g.AddComponent<DentalTooth>();tooth.match=m;tooth.id=id;tooth.body=body;tooth.spawn=position;tooth.crown=new GameObject("Finished original molar crown and tapered roots").transform;tooth.crown.SetParent(g.transform,false);Part(tooth.crown,"Rounded enamel molar crown",enamel,new Vector3(0,1.4f,0),new Vector3(2.1f,2.5f,2.1f));for(int cusp=0;cusp<4;cusp++)Round(tooth.crown,"Sculpted rounded molar cusp",enamel,new Vector3(cusp%2==0?-.55f:.55f,2.55f,cusp<2?-.55f:.55f),new Vector3(1.15f,.85f,1.15f));for(int side=-1;side<=1;side+=2)ServingArt.Part(Folder,tooth.crown,"Tapered non-graphic tooth root",ServingArt.Mesh(Folder,"Curved tapered molar root",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(0,-1.4f),new Vector2(.12f,-1.2f),new Vector2(.4f,-.3f),new Vector2(.5f,.15f),new Vector2(0,.15f)},24)),enamel,new Vector3(side*.45f,0,0),Vector3.one);var c=g.AddComponent<BoxCollider>();c.center=Vector3.up*1.45f;c.size=new Vector3(2.05f,2.8f,2.05f);c.sharedMaterial=contact;tooth.physical=new Collider[]{c};tooth.plaque=Round(tooth.crown,"Actual removable amber tooth plaque",plaque,new Vector3(0,1.6f,-1.04f),new Vector3(1.6f,1.1f,.14f)).transform;tooth.cavity=Round(tooth.crown,"Non-graphic cavity target",dark,new Vector3(0,1.6f,-1.08f),new Vector3(.85f,.8f,.12f)).transform;tooth.filling=Round(tooth.crown,"Actual completed tooth filling",filling,new Vector3(0,1.6f,-1.08f),new Vector3(.87f,.82f